pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy, owner is address(this) by default
        address originalOwner = address(this);
        address newOwner = address(0x1234);

        // Transfer ownership to newOwner
        c.transferOwnership(newOwner);

        // Now originalOwner calls owned() -> should revert in reference
        vm.prank(originalOwner);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: modifier requires msg.sender == owner, but owner is newOwner, so require fails -> revert -> ok == false
        // Bug: modifier requires msg.sender != owner, which is true (0x1234 != 0x...), so no revert -> ok == true
        // Assertion: reference passes (ok == false), bug fails (ok == true) -> assertTrue(!ok) passes reference, fails bug
        assertTrue(!ok);
    }
}

